UNKNOWN.update({17422:'전투기 생산과 채용을 소개하는 재전송이 잘렸다.',17473:'제약사 약가 관련 발언이 문장 중간에서 잘렸다.',18479:'관련 법안에 대한 대통령 발언이 중간에 잘렸다.'})

def main():
    records=[]
    for tone,group in [('positive',POSITIVES),('negative',NEGATIVES),('mixed',MIXED),('neutral',NEUTRALS),('unknown',UNKNOWN)]:
        records.extend({'raw_row':str(k),'tone':tone,'tone_reason_ko':v} for k,v in group.items())
    df=pd.DataFrame(records)
    src=pd.read_csv(ROOT/'data/trump_tweets_analysis_input.csv',dtype=str,keep_default_na=False)
    expected=src.loc[src.additional_status.eq('include_core'),'raw_row'].head(320)
    assert len(df)==320 and df.raw_row.is_unique and set(df.raw_row)==set(expected)
    path=ROOT/'docs/tweet_audit_2026-11-02/tone_core_manual.csv'
    df.to_csv(path,index=False,encoding='utf-8-sig')
    print(df.tone.value_counts().to_dict())

if __name__=='__main__': main()
